import { showModal } from '@ui-kit/Modal';

import AddCustomEquipModal from './AddCustomEquipModal';
import { getEmptyHikingEquip } from '../../../@mappers/equip.mapper';
import { IHikingEquip } from '../../../@types/equip.types';

export function addCustomEquipModal(
  id_hiking: number,
  onAdd: (addedHikingEquip: IHikingEquip) => void,
) {
  showModal({
    children: (closeHandler: () => void) => (
      <AddCustomEquipModal
        data={getEmptyHikingEquip()}
        id_hiking={id_hiking}
        onSave={(newItem) => {
          onAdd(newItem);
          closeHandler();
        }}
        onCancel={closeHandler}
      />
    ),
  });
}
