import React, { useContext } from 'react';

import X from '@pohodnik/icons/svg/Signs/X';

import { selectHikerAsync } from '@components/HikerSelector/hikerSelectHelper';
import PageLoader from '@components/PageLoader';
import { round } from '@helpers/mathHelper';
import notificationHelper, { err, success } from '@helpers/notificationHelper';
import PohAva from '@ui-kit/Ava';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCard from '@ui-kit/Card';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import { confirmModal } from '@ui-kit/Modal';

import { addCustomEquipModal } from './addCustomEquip/addCustomEduipModal';
import { editCustomEquipModal } from './addCustomEquip/editCustomEquipModal';
import CommonEquipItem from './components/CommonEquipItem';
import { AuthContext } from '../../../../contexts/AuthContext';
import {
  confirmHikingCommonEquipToggle,
  deleteHikingCommonEquip,
  getHikingEquip,
  reassignUserEquip,
  saveHikingCommonEquip,
} from '../../@services/equip.service';
import { getHikingFieldsAsync } from '../../@services/hiking.service';
import { getHikingAccessGroupAsync } from '../../@services/hikingRules.service';
import { IHikingFieldsDTO } from '../../@types/DTO/hiking.dto.types';
import { IHikingEquip } from '../../@types/equip.types';
import { HikingAccessGroup } from '../../@types/hiking.rules';

interface IHikingEquipAdminProps {
  id_hiking: number;
}

const HikingEquipAdmin: React.FC<IHikingEquipAdminProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingFieldsDTO>({});
  const [items, setItems] = React.useState<IHikingEquip[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [accessGroup, setAccessGroup] = React.useState<HikingAccessGroup>(
    HikingAccessGroup.Readonly,
  );

  const authContext = useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      await getHikingFieldsAsync(id_hiking, 'name').then(setHikingData);
      await getHikingEquip(id_hiking, false).then(setItems);
      await getHikingAccessGroupAsync(id_hiking).then(setAccessGroup);
    };

    init()
      .catch(err)
      .finally(() => setIsLoading(false));
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  type Aggregation = Record<
    string,
    {
      user: null | IHikingEquip['user'];
      confirmedWeight: number;
      confirmedValue: number;
      totalWeight: number;
      totalValue: number;
      equips: IHikingEquip[];
    }
  >;

  const groups = items.reduce<Aggregation>((acc, val) => {
    const key = val?.user?.id ?? 0;
    if (!acc[key]) {
      acc[key] = {
        user: val.user ? { ...val.user } : null,
        confirmedWeight: 0,
        confirmedValue: 0,
        totalWeight: 0,
        totalValue: 0,
        equips: [],
      };
    }

    acc[key].totalWeight += +val.weight;
    acc[key].totalValue += +val.value;

    if (val.isConfirm) {
      acc[key].confirmedWeight += +val.weight;
      acc[key].confirmedValue += +val.value;
    }

    acc[key].equips.push(val);

    return acc;
  }, {});

  const handleConfirm = async (hikingEquip: IHikingEquip) => {
    try {
      await confirmHikingCommonEquipToggle(id_hiking, hikingEquip);
      setItems(
        items.map((x) =>
          x.id === hikingEquip.id ? { ...x, isConfirm: !hikingEquip.isConfirm } : x,
        ),
      );
    } catch (e) {
      err(e);
    }
  };

  const handleSetUser = async (hikingEquip: IHikingEquip) => {
    try {
      const hiker = await selectHikerAsync(id_hiking, { withMe: true });
      const user: IHikingEquip['user'] = {
        id: hiker.idUser,
        photo: hiker.photo['50'],
        name: [hiker.surname, hiker.name].join(' '),
      };

      if (hikingEquip.id_equip) {
        await reassignUserEquip(id_hiking, hikingEquip.id_equip, user.id);
      } else {
        await saveHikingCommonEquip(id_hiking, { ...hikingEquip, user });
      }

      setItems(items.map((x) => (x.id === hikingEquip.id ? { ...x, user } : x)));
    } catch (e) {
      err(e);
    }
  };

  const handleAdd = () => {
    if (!authContext.user) return;
    addCustomEquipModal(id_hiking, (newItem) => {
      success('Добавлено');
      setItems((cur) => cur.concat(newItem));
    });
  };
  const handleEdit = (hikingEquip: IHikingEquip) => {
    editCustomEquipModal(id_hiking, hikingEquip, (res) =>
      setItems(items.map((x) => (x.id === hikingEquip.id ? { ...x, ...res } : x))),
    );
  };
  const handleDelete = async (hikingEquip: IHikingEquip) => {
    try {
      const is_del = await confirmModal(`Удалить ${hikingEquip.name} ?`);
      if (is_del) {
        await deleteHikingCommonEquip(id_hiking, hikingEquip.id);
        success('Удалено!');
        setItems((cur) => cur.filter((x) => +x.id !== hikingEquip.id));
      }
    } catch (e) {
      err(e);
    }
  };

  const readonly = ![
    HikingAccessGroup.Boss,
    HikingAccessGroup.All,
    HikingAccessGroup.Full,
    HikingAccessGroup.Equip,
  ].includes(accessGroup);

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name ?? '' },
          { href: `/hiking/${id_hiking}/equip/admin`, text: 'Групповое снаряжение', active: true },
        ]}
      />
      <h3 className="mb-3">
        <PohButton variant={ButtonVariant.Primary} className="float-end" onClick={handleAdd}>
          Добавить
        </PohButton>
        Общее снаряжение для похода «{hikingData.name}»
      </h3>

      <PohRow className="mb-2">
        <PohCol sm={12} className="d-flex flex-wrap">
          {items == null && <PageLoader />}
          {items?.length === 0 && <Empty>Нет сборок</Empty>}
          {!!groups &&
            Object.entries(groups).map(([uid, group]) => (
              <PohCard
                key={uid}
                className="w-100 mb-2"
                header={
                  <div className="d-flex m-n2">
                    <PohAva
                      width={48}
                      src={group?.user?.photo}
                      alt={group?.user?.name}
                      icon={<X />}
                    />
                    <div className="ms-2">
                      <b>
                        {group?.user?.name || <span className="text-danger">Не распределено</span>}
                      </b>
                      <br />
                      Утвержденного: {round(group.confirmedWeight / 1000)}&thinsp;кг
                      {' / '}
                      {round(group.confirmedValue / 1000)}&thinsp;л.
                    </div>
                  </div>
                }
              >
                <PohRow className="mb-2">
                  <PohCol sm={6}>
                    <small>Утверждено</small>
                    <PohList
                      data={group.equips
                        .filter((x) => x.isConfirm)
                        .map((hikingEquip) => ({
                          key: hikingEquip.id,
                          content: (
                            <CommonEquipItem
                              data={hikingEquip}
                              onChange={() => handleEdit(hikingEquip)}
                              onDelete={() => handleDelete(hikingEquip)}
                              onConfirm={() => handleConfirm(hikingEquip)}
                              onSetUser={() =>
                                notificationHelper.warn('Сначала снимите утверждение')
                              }
                              readonly={readonly}
                            />
                          ),
                        }))}
                    />
                  </PohCol>
                  <PohCol sm={6}>
                    <small>Ожидает утверждения</small>
                    <PohList
                      data={group.equips
                        .filter((x) => !x.isConfirm)
                        .map((hikingEquip) => ({
                          key: hikingEquip.id,
                          content: (
                            <CommonEquipItem
                              data={hikingEquip}
                              readonly={false}
                              onChange={() => handleEdit(hikingEquip)}
                              onDelete={() => handleDelete(hikingEquip)}
                              onConfirm={() => handleConfirm(hikingEquip)}
                              onSetUser={() => handleSetUser(hikingEquip)}
                            />
                          ),
                        }))}
                    />
                  </PohCol>
                </PohRow>
              </PohCard>
            ))}
        </PohCol>
      </PohRow>
    </PohContainer>
  );
};
export default HikingEquipAdmin;
