import React from 'react';

import { showModal } from '@ui-kit/Modal';

import AddCustomEquipModal from './AddCustomEquipModal';
import { IHikingEquip } from '../../../@types/equip.types';

export function editCustomEquipModal(
  id_hiking: number,
  data: IHikingEquip,
  onSave: (addedHikingEquip: IHikingEquip) => void,
) {
  showModal({
    children: (closeHandler: () => void) => (
      <AddCustomEquipModal
        id_hiking={id_hiking}
        data={data}
        onSave={(newItem) => {
          onSave(newItem);
          closeHandler();
        }}
        onCancel={closeHandler}
      />
    ),
  });
}
