import React, { FormEvent } from 'react';

import Sunglasses from '@pohodnik/icons/svg/RealWorld/Sunglasses';

import { round } from '@helpers/mathHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohAva from '@ui-kit/Ava';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohImageUploader from '@ui-kit/ImageUploader';
import PohInput from '@ui-kit/Input';
import InputTypes from '@ui-kit/Input/InputTypes';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { getEquipSuggest } from './services';
import { saveHikingCommonEquip } from '../../../@services/equip.service';
import { IHikingEquip } from '../../../@types/equip.types';
import EquipOptionsWidget from '../../HikingEquip/components/EquipOptionsWidget';

interface IAddCustomEquipModalProps {
  id_hiking: number;
  data: IHikingEquip;
  onSave: (addedHikingEquip: IHikingEquip) => void;
  onCancel: () => void;
}

const AddCustomEquipModal: React.FC<IAddCustomEquipModalProps> = ({
  id_hiking,
  data,
  onSave,
  onCancel,
}) => {
  const [modelData, setModelData] = React.useState<IHikingEquip>(data);

  const handleSave = async () => {
    try {
      const id = await saveHikingCommonEquip(id_hiking, modelData);
      onSave({ ...modelData, id });
    } catch (e) {
      notificationHelper.error((e as Error).message);
    }
  };

  const handleChange = (fieldName: keyof IHikingEquip) => (value: any) =>
    setModelData({ ...modelData, [fieldName]: value });

  return (
    <PohContainer
      as="form"
      onSubmit={(e: FormEvent) => {
        e.preventDefault();
        handleSave();
      }}
    >
      <PohRow>
        <PohCol sm={8} className="mb-sm-3">
          <PohInput
            label="Название"
            type={InputTypes.autocomplete}
            value={modelData.name}
            autoFocus
            onChange={(sel: any) => {
              if (sel?.text) {
                setModelData({ ...modelData, ...sel, name: sel.text });
              }
            }}
            // onBlur={(a, b) => console.log('PohInputBlur', a, b)}
            onRealChange={(val: any) => handleChange('name')(val?.text || val || '')}
            autocompleteOpts={{
              data: getEquipSuggest,

              renderItem: ({ text, photo, weight, value }) => (
                <div className="d-flex justify-content-between align-items-center flex-nowrap ms-n3 me-n3">
                  <div className="d-flex align-items-center">
                    <PohAva
                      src={photo}
                      alt={text}
                      width={32}
                      icon={<Sunglasses />}
                      className="me-2"
                    />
                    {text}
                  </div>
                  <EquipOptionsWidget weight={round(weight / 1000)} value={round(+value)} />
                </div>
              ),
              allowCustom: true,
            }}
          />

          <PohInput
            label="Вес, грамм"
            type={InputTypes.number}
            min={0}
            max={20000}
            step={1}
            maxLength={5}
            value={modelData.weight.toString()}
            onChange={handleChange('weight')}
            required
          />
          <PohInput
            label="Объем, 1/1000 литра (милилитр)"
            type={InputTypes.number}
            min={100}
            max={50000}
            step={1}
            maxLength={5}
            value={modelData.value.toString()}
            onChange={handleChange('value')}
            required
          />
        </PohCol>
        <PohCol sm={4}>
          <PohImageUploader
            width={255}
            height={255}
            ratio={1}
            sizes={[255]}
            src={modelData.photo}
            onChange={(src) => {
              handleChange('photo')(src);
            }}
            folder="images/equip"
          />
        </PohCol>
      </PohRow>
      <footer className="mt-4">
        <PohButton variant={ButtonVariant.Secondary} onClick={onCancel}>
          Отмена
        </PohButton>{' '}
        &nbsp;
        <PohButton variant={ButtonVariant.Primary} type="submit">
          Сохранить
        </PohButton>
      </footer>
    </PohContainer>
  );
};
export default AddCustomEquipModal;
